package com.pocketmusic.android;
import android.content.*;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.util.*;
import com.google.android.material.bottomsheet.*;
import static com.pocketmusic.android.DesignTokens.*;

/** Full-height, filtered download manager. Updating progress never rebuilds thumbnail rows. */
final class DownloadsSheet extends BottomSheetDialog {
 interface Actions {void play(File file);void library();void folder();void smart();}
 private final Context c;private final Actions actions;private final LinearLayout rows;private final TextView summary,location,smartState;private final ProgressBar progress,smartProgress;private final Button cancelAll;private final Map<String,Item> items=new HashMap<>();private final Map<String,Button> filters=new LinkedHashMap<>();private String filter="all",layoutKey="";
 DownloadsSheet(Context context,Actions actions){super(context);c=context;this.actions=actions;LinearLayout root=column();root.setBackgroundColor(COLOR_BG);root.setPadding(dp(20),dp(16),dp(20),dp(16));root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(dp(20),dp(12),dp(20),in.getSystemWindowInsetBottom()+dp(16));return in;});LinearLayout heading=row();TextView title=text("Downloads",26,COLOR_TEXT);title.setTypeface(null,android.graphics.Typeface.BOLD);heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));heading.addView(button("Done",this::dismiss));root.addView(heading);
  summary=text("",14,COLOR_ACCENT);summary.setPadding(0,dp(12),0,dp(6));root.addView(summary);smartState=text("",13,COLOR_TEXT_MUTED);smartState.setPadding(0,dp(4),0,dp(8));smartState.setMinHeight(dp(40));smartState.setOnClickListener(v->{dismiss();actions.smart();});root.addView(smartState);smartProgress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);root.addView(smartProgress,new LinearLayout.LayoutParams(-1,dp(8)));location=text("",12,COLOR_ACCENT);location.setGravity(Gravity.CENTER_VERTICAL);location.setMinHeight(dp(40));location.setOnClickListener(v->{dismiss();actions.folder();});root.addView(location);progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(12)));
  HorizontalScrollView strip=new HorizontalScrollView(c);strip.setHorizontalScrollBarEnabled(false);LinearLayout chips=row();String[] keys={"all","active","attention","finished"},labels={"All","Active","Attention","Finished"};for(int i=0;i<keys.length;i++){String key=keys[i];Button chip=button(labels[i],()->{filter=key;layoutKey="";refresh();});chip.setMinWidth(dp(48));chip.setMinimumWidth(dp(48));chip.setPadding(dp(12),0,dp(12),0);filters.put(key,chip);LinearLayout.LayoutParams spacing=new LinearLayout.LayoutParams(-2,-2);spacing.rightMargin=dp(6);chips.addView(chip,spacing);}strip.addView(chips);root.addView(strip);
  LinearLayout tools=row();cancelAll=button("Cancel all",()->{command("cancel",null);refresh();});tools.addView(cancelAll,new LinearLayout.LayoutParams(0,-2,1));tools.addView(button("Clear history",()->{DownloadService.clearFinished(c);layoutKey="";refresh();}),new LinearLayout.LayoutParams(0,-2,1));root.addView(tools);TextView hint=text("Clearing history keeps your saved files.",12,COLOR_TEXT_MUTED);hint.setPadding(0,0,0,dp(10));root.addView(hint);
  ScrollView scroll=new ScrollView(c);scroll.setFillViewport(true);rows=column();scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);setOnShowListener(d->{getBehavior().setSkipCollapsed(true);getBehavior().setFitToContents(false);getBehavior().setExpandedOffset(0);getBehavior().setState(BottomSheetBehavior.STATE_EXPANDED);android.widget.FrameLayout sheet=findViewById(com.google.android.material.R.id.design_bottom_sheet);if(sheet!=null){ViewGroup.LayoutParams params=sheet.getLayoutParams();params.height=ViewGroup.LayoutParams.MATCH_PARENT;sheet.setLayoutParams(params);}});refresh();
 }
 private int dp(int value){return GlassTheme.dp(c,value);}private LinearLayout column(){LinearLayout l=new LinearLayout(c);l.setOrientation(LinearLayout.VERTICAL);return l;}private LinearLayout row(){LinearLayout l=new LinearLayout(c);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private TextView text(String value,int size,int color){TextView t=new TextView(c);t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}private Button button(String title,Runnable action){Button b=UiComponents.action(c,title,0,false,action);b.setTextSize(12);return b;}
 private void command(String action,String key){Intent intent=new Intent(c,DownloadService.class).setAction(action);if(key!=null)intent.putExtra("job",key);c.startForegroundService(intent);}
 void refresh(){smartState.setText(SmartDownloads.enabled(c)?"Smart downloads · "+SmartDownloads.status(c)+"  ›":"Smart downloads · Set up automatic offline music  ›");smartProgress.setVisibility(SmartDownloads.busy()?View.VISIBLE:View.GONE);smartProgress.setProgress(c.getSharedPreferences("music",0).getInt("smartProgress",0));List<DownloadQueue.Job> jobs=DownloadService.jobs(c);summary.setText(DownloadPresentation.summary(jobs));location.setText("Save folder · "+DownloadFolder.label(c)+"  ›");boolean pending=jobs.stream().anyMatch(DownloadQueue.Job::pending);progress.setVisibility(pending?View.VISIBLE:View.GONE);progress.setIndeterminate(DownloadPresentation.unknown(jobs));progress.setProgress(DownloadPresentation.progress(jobs));cancelAll.setVisibility(pending?View.VISIBLE:View.GONE);for(Map.Entry<String,Button> entry:filters.entrySet()){boolean selected=entry.getKey().equals(filter);((com.google.android.material.button.MaterialButton)entry.getValue()).setBackgroundTintList(android.content.res.ColorStateList.valueOf(selected?COLOR_ACCENT:COLOR_SURFACE_RAISED));entry.getValue().setTextColor(selected?COLOR_ON_ACCENT:COLOR_TEXT);}
  StringBuilder key=new StringBuilder(filter);Set<String> present=new HashSet<>();for(DownloadQueue.Job job:jobs){key.append(job.key).append(DownloadPresentation.group(job));present.add(job.key);}items.keySet().retainAll(present);if(!key.toString().equals(layoutKey)){layoutKey=key.toString();rows.removeAllViews();int count=0;for(String group:List.of("active","attention","finished")){if(!filter.equals("all")&&!filter.equals(group))continue;List<DownloadQueue.Job> selected=new ArrayList<>();for(DownloadQueue.Job job:jobs)if(DownloadPresentation.group(job).equals(group))selected.add(job);if(selected.isEmpty())continue;TextView label=text(group.equals("active")?"In progress":group.equals("attention")?"Needs attention":"Finished",16,COLOR_TEXT);label.setPadding(0,dp(14),0,dp(8));rows.addView(label);Collections.reverse(selected);for(DownloadQueue.Job job:selected){Item item=items.computeIfAbsent(job.key,k->new Item(job));if(item.getParent()!=null)((ViewGroup)item.getParent()).removeView(item);rows.addView(item);count++;}}
   if(count==0){TextView empty=text(filter.equals("all")?"Your queue is empty\nFind a song in Search to download it.":"Nothing here right now",18,COLOR_TEXT_MUTED);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(12),dp(60),dp(12),dp(60));rows.addView(empty);}}
  for(Item item:items.values())item.update();
 }
 private final class Item extends LinearLayout {
  final DownloadQueue.Job job;final TextView state,transfer;final ProgressBar bar;final Button cancel,retry,play,details;
  Item(DownloadQueue.Job job){super(c);this.job=job;setOrientation(VERTICAL);setPadding(dp(12),dp(12),dp(12),dp(12));setBackground(GlassTheme.panel(c,18,false));LinearLayout.LayoutParams card=new LinearLayout.LayoutParams(-1,-2);card.bottomMargin=dp(10);setLayoutParams(card);LinearLayout top=row();ImageView art=new ImageView(c);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(GlassTheme.coverFrame(c));art.setClipToOutline(true);Track known=MusicTaste.track(c,job.id);Artwork.load(c,known==null?new Track(job.id,job.title):known,art,dp(52));top.addView(art,new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout words=column();words.setPadding(dp(12),0,0,0);TextView title=text(job.title,15,COLOR_TEXT);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(title);words.addView(text(job.format.toUpperCase(Locale.ROOT),12,COLOR_TEXT_MUTED));top.addView(words,new LinearLayout.LayoutParams(0,-2,1));addView(top);state=text("",13,COLOR_ACCENT);state.setPadding(0,dp(10),0,dp(4));addView(state);bar=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setContentDescription("Download progress for "+job.title);addView(bar,new LinearLayout.LayoutParams(-1,dp(8)));transfer=text("",12,COLOR_TEXT_MUTED);addView(transfer);LinearLayout controls=row();cancel=button("Cancel",()->command("cancelJob",job.key));retry=button("Retry",()->command("retry",job.key));play=button("Play",()->{File file=MusicRepository.downloaded(c,job.id,job.format);dismiss();if(file!=null&&TrackFiles.audio(file))actions.play(file);else actions.library();});details=button("Details",()->new com.google.android.material.dialog.MaterialAlertDialogBuilder(c).setTitle("Download details").setMessage(DownloadErrors.redact(job.error)).setPositiveButton("Close",null).show());for(Button action:List.of(cancel,retry,play,details)){LinearLayout.LayoutParams spacing=new LinearLayout.LayoutParams(-2,-2);spacing.rightMargin=dp(6);controls.addView(action,spacing);}addView(controls);}
  void update(){state.setText(DownloadPresentation.state(job));state.setTextColor(DownloadPresentation.group(job).equals("attention")?0xffffb4ab:COLOR_ACCENT);bar.setVisibility(job.pending()?View.VISIBLE:View.GONE);bar.setIndeterminate(job.progress<0);if(job.progress>=0)bar.setProgress(job.progress);String value=DownloadPresentation.transfer(job);transfer.setText(value);transfer.setVisibility(value.isEmpty()?View.GONE:View.VISIBLE);cancel.setVisibility(job.pending()?View.VISIBLE:View.GONE);boolean retryable=DownloadPresentation.group(job).equals("attention")||"cancelled".equals(job.state);retry.setVisibility(retryable?View.VISIBLE:View.GONE);retry.setText("saveFailed".equals(job.state)?"Retry saving":"Retry");File file=(job.state.equals("done")||job.state.equals("saveFailed"))?MusicRepository.downloaded(c,job.id,job.format):null;play.setVisibility(file==null?View.GONE:View.VISIBLE);play.setText(file!=null&&TrackFiles.audio(file)?"Play":"Library");details.setVisibility(job.error.isEmpty()?View.GONE:View.VISIBLE);}
 }
}
